\label{Invariant diagram definition}
An {\bf{invariant diagram}} is a collection $\mathcal{I}$ of pairs of formulas satisfying the following. 
\begin{itemize}
\item[(a)] If $(P(x_0, \dots, x_{n-1}), \psi(y_0, \dots, y_{k-1})) \in \mathcal{I}$ then $\{y_i\}_{i \in [k]} \subseteq \{x_i\}_{i \in [n]}$ and $P \in \ensuremath{\mathfrak{L}}_b$, and either $\psi(y_0, \dots, y_{k-1})$ is an atomic formula or the negation of an atomic formula.

\item[(b)] For every $Q\in \ensuremath{\mathfrak{L}}_b^n$, $R \in \ensuremath{\mathfrak{L}}_b^k\cup \ensuremath{\mathfrak{L}}_c^k$ and $\<j_i\>_{i \in [k]} \subseteq [n]$ precisely one of the following holds:
\begin{itemize}
\item $(Q(x_0, \dots, x_{n-1}), R(x_{j_0}, \dots, x_{j_{k-1}})) \in \mathcal{I}$, or 

\item $(Q(x_0, \dots, x_{n-1}), \neg R(x_{j_0}, \dots, x_{j_{k-1}})) \in \mathcal{I}$. 
\end{itemize}

\item[(c)] For each $Q \in \ensuremath{\mathfrak{L}}_b$ there is an $(\ensuremath{\mathfrak{L}}_b\cup\ensuremath{\mathfrak{L}}_c)$-structure ${\ensuremath{\mathcal{M}}}$ where 
\begin{itemize}
\item ${\ensuremath{\mathcal{M}}} \models 
\operatorname{Th}_{\operatorname{SGeo}}(#1, #2, #3)
<\ensuremath{\mathfrak{L}}_a>[\ensuremath{\mathfrak{L}}_b](\ensuremath{\mathfrak{L}}_c)$, 

\item ${\ensuremath{\mathcal{M}}} \models (\exists {\bm{x}})\, Q({\bm{x}})$,  and

\item for all $Q^* \in \ensuremath{\mathfrak{L}}_b^n$ and $\<j_i\>_{i \in [k]} \subseteq [n]$ with $\bigl(Q^*(x_0, \dots, x_{n-1}), \psi(x_{j_0}, \dots, x_{j_{k-1}})\bigr) \in \mathcal{I}$, we have
\[
{\ensuremath{\mathcal{M}}} \models (\forall x_0, \dots, x_{n-1})\, Q^*(x_0, \dots, x_{n-1}) \rightarrow \psi(x_{j_0}, \dots, x_{j_{k-1}}).
\]
\end{itemize}
\end{itemize}

\label{Invariant system definition}
An {\bf{invariant system}} (on $\ensuremath{\mathfrak{L}}_b$) is a collection of maps $\ensuremath{\mathop{\pmb{\tau}}} = \<\tau_\beta\>_{\beta \in \ensuremath{\omega}_1}$ which satisfy the following.  
\begin{itemize}

\item[(a)] For all $\beta \in \ensuremath{\omega}_1$, we have $\tau_\beta\: \ensuremath{\mathfrak{L}}_b \to \ensuremath{\mathfrak{L}}_b$. 

\item[(b)] For all $n \geq 1$, for all $\beta \in \ensuremath{\omega}_1$,  we have $\tau_\beta\ensuremath{\!\upharpoonright_{\ensuremath{\mathfrak{L}}_b^n}}:\ensuremath{\mathfrak{L}}_b^n \to \ensuremath{\mathfrak{L}}_b^n$, i.e., for all invariants $Q$, $\tau_\beta(Q)$ has the same arity as $Q$. 

\item[(c)] For all $\alpha \leq \beta \in \ensuremath{\omega}_1$, we have $\tau_\alpha \circ \tau_\beta = \tau_\beta \circ \tau_\alpha = \tau_\alpha$.

\item[(d)] If for all $\beta \in \ensuremath{\omega}_1$ we have $\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta] = \{Q \in \ensuremath{\mathfrak{L}}_b \,:\, \tau_\beta(Q) = Q\}$, then 
\begin{itemize}
\item[(i)] for all $\beta \in \ensuremath{\omega}_1$, we have $|\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta]| \leq \ensuremath{\omega}$,

\item[(ii)] for all $\beta \in \ensuremath{\omega}_1$, we have $\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta] \neq \ensuremath{\mathfrak{L}}_b$, and 

\item[(iii)] $\ensuremath{\mathfrak{L}}_b = \bigcup_{\beta \in \ensuremath{\omega}_1}\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta]$. 
\end{itemize}
We also let $\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \ensuremath{\omega}_1] = \ensuremath{\mathfrak{L}}_b$. 

\end{itemize}
For $\beta \in \ensuremath{\omega}_1$ we say that the elements of $\ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta]$ are {\bf{$\beta$-invariants}}. We define the {\bf{$\ensuremath{\mathop{\pmb{\tau}}}$-rank}} of an invariant $Q$, denoted by $
