Suppose ${\ensuremath{\mathcal{M}}}$ is an $(\ensuremath{\mathfrak{L}}_b \cup \ensuremath{\mathfrak{L}}_c)$-structure. We define the {\bf{$\beta$-projection}} of ${\ensuremath{\mathcal{M}}}$, denoted by $\tau_\beta({\ensuremath{\mathcal{M}}})$, to be the $(\ensuremath{\mathfrak{L}}_b \cup \ensuremath{\mathfrak{L}}_c)$-structure satisfying the following. 
\begin{itemize}
\item ${\ensuremath{\mathcal{M}}}$ and $\tau_\beta({\ensuremath{\mathcal{M}}})$ have the same underlying set $M$. 

\item For all relation symbols $R \in \ensuremath{\mathfrak{L}}_c^n$ and all tuples $a_0, \dots, a_{n-1} \in M$, 
\[
\tau_\beta({\ensuremath{\mathcal{M}}}) \models R(a_0, \dots, a_{n-1})\text{ if and only if }{\ensuremath{\mathcal{M}}} \models R(a_0, \dots, a_{n-1}).
\]

\item For all relation symbols $R \in \ensuremath{\mathfrak{L}}_b^n$ and all tuples $a_0, \dots, a_{n-1} \in M$, we have $\tau_\beta({\ensuremath{\mathcal{M}}}) \models R(a_0, \dots, a_{n-1})$ if and only if there is an $R^* \in \ensuremath{\mathfrak{L}}_b$ with $\tau_\beta(R^*) = R$ and ${\ensuremath{\mathcal{M}}} \models R^*(a_0, \dots, a_{n-1})$. 

\end{itemize}

