\]

\item[(c)] For all $Q, R \in \ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta]$ with $(Q({\bm{x}}{\bm{y}}), R({\bm{x}})) \in \mathcal{I}$, we have 
\[
(\forall {\bm{x}})\, R({\bm{x}}) \rightarrow (\exists {\bm{y}})\bigvee_{\substack{Q^* \in \ensuremath{\mathfrak{L}}_b[\ensuremath{\mathop{\pmb{\tau}}}, \beta]\\ \tau_\alpha(Q^*) =\tau_\alpha(Q)}} Q^*({\bm{x}}{\bm{y}}).
\]
\end{itemize}

