}
<\mathcal{I}>[\ensuremath{\mathop{\pmb{\tau}}}](\alpha)$, i.e. ${\ensuremath{\mathcal{M}}}$ satisfies $\alpha$-density. 

\item For all $\alpha < \beta$ and all ${\ensuremath{\mathcal{M}}} \in K_\beta$, $\tau_\alpha({\ensuremath{\mathcal{M}}}) \in K_\alpha$. 
\end{itemize}

We will let $K = \bigcup_{\beta \in \ensuremath{\omega}_1} K_\beta$. We call $K_{-\infty} = \{{\ensuremath{\mathcal{M}}}\ensuremath{\!\upharpoonright_{\ensuremath{\mathfrak{L}}_c}} \,:\, {\ensuremath{\mathcal{M}}} \in K\}$ the {\bf{base}} of $\ensuremath{\mathop{\pmb{K}}}$.

\label{Knight systems imply equiv-beta equivalence}
Suppose  that
\begin{itemize}

\item[(a)] $\<K_\beta\>_{\beta \in \ensuremath{\omega}_1}$ is a weak Knight system (for $\mathcal{I}$ and $\ensuremath{\mathop{\pmb{\tau}}}$), 

\item[(b)] ${\ensuremath{\mathcal{M}}}, {\ensuremath{\mathcal{N}}} \in K_\beta$,  and

\item[(c)] there is an invariant $Q \in \ensuremath{\mathfrak{L}}_b$ such that ${\ensuremath{\mathcal{M}}} \models (\exists {\bm{x}})\, Q({\bm{x}})$ and ${\ensuremath{\mathcal{N}}} \models (\exists {\bm{x}})\, Q({\bm{x}})$. 
\end{itemize}
Then ${\ensuremath{\mathcal{M}}}\ensuremath{\!\upharpoonright_{\ensuremath{\mathfrak{L}}_c}} \equiv_\beta {\ensuremath{\mathcal{N}}}\ensuremath{\!\upharpoonright_{\ensuremath{\mathfrak{L}}_c}}$.

For $i \leq \beta$ let $I_i$ be the collection of pairs $({\ensuremath{\mathbf{a}}}, {\ensuremath{\mathbf{b}}})$ such that 
\begin{itemize}
\item ${\ensuremath{\mathbf{a}}} \subseteq {\ensuremath{\mathcal{M}}}$ and ${\ensuremath{\mathbf{b}}} \subseteq {\ensuremath{\mathcal{N}}}$ are closed and of the same length, and

\item there is a $Q \in \ensuremath{\mathfrak{L}}_b$ such that $\tau_i({\ensuremath{\mathcal{M}}}) \models Q({\ensuremath{\mathbf{a}}})$ and $\tau_i({\ensuremath{\mathcal{N}}}) \models Q({\ensuremath{\mathbf{b}}})$. 
\end{itemize}

It suffices to show that $\<I_i\>_{i \leq \beta}$ is a back and forth system. The fact that when $i < j \leq \beta$ we have $I_j \subseteq I_i$ follows from the compatibility of $\ensuremath{\mathop{\pmb{\tau}}}$ and $\mathcal{I}$ and the fact that $\tau_i = \tau_i \circ \tau_{j}$. Further, because ${\ensuremath{\mathcal{M}}}, {\ensuremath{\mathcal{N}}} \in K_\beta$ we have $\max\{
