\cref{Back and forth system definition} (b) is immediate 
and \cref{Back and forth system definition} (c) follows from the fact that invariants determine the quantifier-free $\ensuremath{\mathfrak{L}}_c$-structure on their arguments. 

We now show \cref{Back and forth system definition} (d.i); the proof of \cref{Back and forth system definition} (d.ii) is identical. Suppose $i < j \leq \beta$, $({\ensuremath{\mathbf{a}}}, {\ensuremath{\mathbf{b}}}) \in I_{j}$ and ${\ensuremath{\mathbf{a}}} {\ensuremath{\mathbf{a}}}^*$ is closed in ${\ensuremath{\mathcal{M}}}$. Let $P_{{\ensuremath{\mathbf{a}}}}, P_{{\ensuremath{\mathbf{b}}}}, Q_{{\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*} \in \ensuremath{\mathfrak{L}}_b$ be such that $\tau_{j}({\ensuremath{\mathcal{M}}}) \models P_{{\ensuremath{\mathbf{a}}}}({\ensuremath{\mathbf{a}}})$, $\tau_{j}({\ensuremath{\mathcal{M}}}) \models Q_{{\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*}({\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*)$ and $\tau_{j}({\ensuremath{\mathcal{N}}}) \models P_{{\ensuremath{\mathbf{b}}}}({\ensuremath{\mathbf{b}}})$. We then have $(Q_{{\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*}, P_{\ensuremath{\mathbf{a}}}) \in \mathcal{I}$ and $P_{\ensuremath{\mathbf{a}}} = P_{\ensuremath{\mathbf{b}}}$. 

Because $\tau_{j}({\ensuremath{\mathcal{N}}}) \in K_{j}$ we have that $\tau_{j}({\ensuremath{\mathcal{N}}})$ satisfies $i$-density. Therefore there must be some ${\ensuremath{\mathbf{b}}}^* \subseteq {\ensuremath{\mathcal{N}}}$ and $Q_{{\ensuremath{\mathbf{b}}}{\ensuremath{\mathbf{b}}}^*} \in\ensuremath{\mathfrak{L}}_b$ such that $\tau_{j}({\ensuremath{\mathcal{N}}}) \models Q_{{\ensuremath{\mathbf{b}}}{\ensuremath{\mathbf{b}}}^*}({\ensuremath{\mathbf{b}}}{\ensuremath{\mathbf{b}}}^*)$ and $\tau_i(Q_{{\ensuremath{\mathbf{b}}}{\ensuremath{\mathbf{b}}}^*}) = \tau_i(Q_{{\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*})$. But then $({\ensuremath{\mathbf{a}}}{\ensuremath{\mathbf{a}}}^*, {\ensuremath{\mathbf{b}}}{\ensuremath{\mathbf{b}}}^*) \in I_i$. As $({\ensuremath{\mathbf{a}}}, {\ensuremath{\mathbf{b}}})$ was arbitrary this implies \cref{Back and forth system definition} (d.i) and so $\<I_i\>_{i \leq \beta}$ is a back and forth system.

\label{Weak Knight systems and perfect sets of models}
Suppose that
\begin{itemize}
\item[(a)] $\ensuremath{\mathop{\pmb{K}}} = \<K_\beta\>_{\beta \in \ensuremath{\omega}_1}$ is a weak Knight system,  and

\item[(b)] for all $\beta \in \ensuremath{\omega}_1$, 
\[
\{{\ensuremath{\mathcal{M}}} \in K_{-\infty} \,:\, (\forall {\ensuremath{\mathcal{N}}} \in K_\beta)\, {\ensuremath{\mathcal{N}}}\ensuremath{\!\upharpoonright_{\ensuremath{\mathfrak{L}}_c}} \neq {\ensuremath{\mathcal{M}}}\}
\]
has countably many isomorphism classes. 

\end{itemize}
Then $K_{-\infty}$ does not contain a perfect set of non-isomorphic models.

\label{Nice tuples definition}
Suppose that $\ensuremath{\mathop{\pmb{K}}} = \<K_\beta\>_{\beta \in \ensuremath{\omega}_1}$ is a weak Knight system (for $(\mathcal{I}, \ensuremath{\mathop{\pmb{\tau}}})$), that ${\ensuremath{\mathcal{M}}}$ is an $\ensuremath{\mathfrak{L}}_c$-structure, and that ${\ensuremath{\mathbf{a}}} \subseteq {\ensuremath{\mathcal{M}}}$ is closed. We say that ${\ensuremath{\mathbf{a}}}$ is {\bf{eventually determined in ${\ensuremath{\mathcal{M}}}$ with respect to $\ensuremath{\mathop{\pmb{K}}}$}} if there are $\alpha_{\ensuremath{\mathbf{a}}} \in \ensuremath{\omega}_1$ and $Q \in \ensuremath{\mathfrak{L}}_b$ satisfying the following conditions.  
\begin{itemize}
\item There is some lift ${\ensuremath{\mathcal{M}}}^*$ of ${\ensuremath{\mathcal{M}}}$ with ${\ensuremath{\mathcal{M}}}^* \in K_{\alpha_{\ensuremath{\mathbf{a}}}}$ and ${\ensuremath{\mathcal{M}}}^*\models Q({\ensuremath{\mathbf{a}}})$. 

\item Whenever $\alpha^* > \alpha_{{\ensuremath{\mathbf{a}}}}$ and ${\ensuremath{\mathcal{M}}}^*$ is a lift of ${\ensuremath{\mathcal{M}}}$ with ${\ensuremath{\mathcal{M}}}^* \in K_{\alpha^*}$ then ${\ensuremath{\mathcal{M}}}^* \models Q({\ensuremath{\mathbf{a}}})$. 

\end{itemize}
When the structure and weak Knight system are understood, we simply say that a tuple is  ``eventually determined''.

We say that ${\ensuremath{\mathcal{M}}}$ is {\bf{eventually determined with respect to $\ensuremath{\mathop{\pmb{K}}}$}} if every closed tuple in ${\ensuremath{\mathcal{M}}}$ is eventually determined.

\label{Main theorem about niceness}
